using System.ComponentModel.DataAnnotations;
using Practica04.Emergency.Domain.Model.ValueObjects;
namespace Practica04.Emergency.Interfaces.Rest.Resources;

/// <summary>Accepts primitive fields for the incident value objects; the ID is generated by persistence.</summary>
public record CreateEmergencyIncidentResource(
    [Required(ErrorMessage = "This field is required.")] Guid? GuidCode,
    [Required(ErrorMessage = "This field is required.")] Guid? ResponseUnitId,
    [Required(ErrorMessage = "This field is required.")] DateTime? ReportedAt,
    [Required(ErrorMessage = "This field is required.")] DateTime? SlaDeadLine,
    [Required(ErrorMessage = "This field is required.")] decimal? DispatchOperationalCostValue,
    [Required(ErrorMessage = "This field is required.")] string DispatchOperationalCostCurrency,
    IncidentStatus Status = IncidentStatus.Pending,
    string? Description = null);




